probes.library-open.mjs:
// File: library-open.mjs (the timing-checks-in-the-page skill)
//
// A probe: a module of agda-algebras opened read-only from the Explorer
// (issue 10).  For each module, a fresh profile; once the default Main is
// checked, Enter on the module's row in the Explorer; the page asks before
// it fetches the module's closure, and the probe answers FETCH (fetch) or
// SOURCE (check from source).  It times the mount (from the answer to the
// heading's "Loading <module>…"), the load (the page's own duration), and
// a hover over a word of the module (from the pointer's arrival to the
// language server's tooltip), and counts the load's Checking lines (an
// Infer of `Set` shows the compiler log).  Then a reload in the same
// profile, and the same module opened again: mounted from the browser's
// store (or, after SOURCE, from what the drive persisted).  One JSON line
// per visit, with the load average.
//
//   CHROME=... REPO=... node library-open.mjs SITE ROUNDS fetch|source MODULE|LINE|WORD...
//
// where LINE is a line of the module, exactly as the editor draws it, and
// WORD a word after its colon to hover over (its last character).

import { readFileSync } from "node:fs";
import { loadavg } from "node:os";

const repo = process.env.REPO;
const cdp = await import(`${repo}/scripts/browser-check/cdp.mjs`);
const { serve } = await import(`${repo}/scripts/browser-check/serve.mjs`);
const [site, roundsText, answer, ...specs] = process.argv.slice(2);
const rounds = Number(roundsText);
const RECORDER = readFileSync(`${repo}/scripts/browser-check/run.mjs`, "utf8").match(/const RECORDER = `([\s\S]*?)`;\n/)[1]
  .replaceAll("\\\\", "\\").replace('${JSON.stringify("/agda-algebras/interfaces/")}', '"/agda-algebras/interfaces/"');
const look = () => ({
  status: document.querySelector(".inspector-status")?.textContent?.trim() ?? "",
  consent: document.querySelector(".consent-size")?.dataset.bytes ?? null,
  busy: document.querySelector(".spin") !== null,
  error: document.querySelector(".action-error span")?.textContent?.trim() ?? null,
  tab: document.querySelector(".editor-tab.active")?.getAttribute("title") ?? null,
  note: document.querySelector(".plan-note")?.textContent?.trim() ?? null,
  result: document.querySelector(".result-card pre")?.textContent ?? null,
  log: document.querySelector(".compiler-log pre")?.textContent ?? null,
  now: performance.now(),
});
const sleep = (ms) => new Promise((done) => setTimeout(done, ms));
const until = async (page, predicate, ms = 900_000) => {
  const start = Date.now();
  for (;;) {
    let s;
    try { s = await page.eval(look); } catch { s = null; }
    if (s?.error) throw new Error(s.error);
    if (s && predicate(s)) return s;
    if (Date.now() - start > ms) throw new Error(`timed out; last ${JSON.stringify(s)}`);
    await sleep(50);
  }
};
const seconds = (text) => { const m = text.match(/· (?:(\d+)m )?([\d.]+) ?(ms|s)$/); return m ? Number(m[1] ?? 0) * 60 + Number(m[2]) / (m[3] === "ms" ? 1000 : 1) : NaN; };
const open = async (page, module) => {
  await page.eval(() => document.querySelector('.explorer input[type="search"]').focus());
  await page.press("a", "KeyA", 65, 2);
  await page.type(module);
  await until(page, () => true, 5_000);
  for (let i = 0; i < 50; i++) {
    if (await page.eval((id) => document.querySelector(`.explorer [data-id="${id}"]`) !== null, `agda-algebras:${module}`)) break;
    await sleep(100);
  }
  await page.eval((id) => document.querySelector(`.explorer [data-id="${id}"]`).focus(), `agda-algebras:${module}`);
  const at = await page.eval(() => performance.now());
  await page.press("Enter", "Enter", 13);
  return at;
};
const hover = async (page, line, word) => {
  const point = await page.eval(async ({ line, word }) => {
    const scroller = document.querySelector(".cm-scroller");
    scroller.scrollTop = 0;
    for (let tries = 0; tries < 200; tries++) {
      const element = [...document.querySelectorAll(".cm-content .cm-line")].find((l) => l.textContent === line);
      if (element) {
        element.scrollIntoView({ block: "center" });
        await new Promise((done) => requestAnimationFrame(() => setTimeout(done, 50)));
        const offset = element.textContent.indexOf(word, element.textContent.indexOf(":")) + word.length - 1;
        const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
        for (let seen = 0, node; (node = walker.nextNode()); seen += node.length)
          if (seen + node.length > offset) {
            const range = document.createRange();
            range.setStart(node, offset - seen);
            range.setEnd(node, offset + 1 - seen);
            const box = range.getBoundingClientRect();
            return { x: box.left + box.width / 2, y: box.top + box.height / 2 };
          }
      }
      scroller.scrollTop += 300;
      await new Promise((done) => setTimeout(done, 50));
    }
    return null;
  }, { line, word });
  if (!point) return { answer: null, ms: null };
  await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: point.x - 40, y: point.y - 40 });
  await sleep(100);
  const start = Date.now();
  await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: point.x, y: point.y });
  for (;;) {
    const got = await page.eval(() => document.querySelector(".cm-lsp-hover-tooltip:not(.cm-lsp-hover-tooltip--loading)")?.textContent ?? null);
    if (got !== null) { await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 5, y: 5 }); return { answer: got.replace(/\s+/g, " ").trim().slice(0, 120), ms: Date.now() - start }; }
    if (Date.now() - start > 300_000) return { answer: null, ms: null };
    await sleep(50);
  }
};
const checking = async (page) => {
  await page.eval(() => [...document.querySelectorAll(".command-strip button")].find((b) => b.title.startsWith("Infer")).click());
  await sleep(200);
  await page.eval(() => { const i = document.querySelector("#command-input"); i.value = "Set"; i.dispatchEvent(new Event("input", { bubbles: true })); i.form.requestSubmit(); });
  const s = await until(page, (s) => !s.busy && s.status === "Inferred type", 120_000);
  return [...(s.log ?? "").matchAll(/Checking (\S+) \(/g)].map((m) => m[1]);
};
const visit = async (page, server, module, line, word, first) => {
  const from = server.log.length;
  const opened = await open(page, module);
  const s0 = await until(page, (s) => s.consent !== null || (!s.busy && s.tab?.includes(module.split(".").join("/")) && / · /.test(s.status)));
  let answered = null, stated = null;
  if (s0.consent !== null) {
    stated = Number(s0.consent);
    answered = await page.eval((answer) => { document.querySelector(answer === "fetch" ? ".consent-fetch" : ".consent-source").click(); return performance.now(); }, answer);
  }
  const done = await until(page, (s) => !s.busy && s.consent === null && / · /.test(s.status));
  const events = await page.eval(() => window.__browserCheck);
  const loading = events.find((e) => e.t >= (answered ?? opened) && e.name === "status" && /^Loading /.test(e.text ?? ""))?.t;
  const archives = server.log.slice(from).filter((r) => r.url.startsWith("/agda-algebras/interfaces/"));
  const h = await hover(page, line, word);
  const checked = await checking(page);
  return {
    module, visit: first ? "first" : "second", answer: s0.consent !== null ? answer : "not asked", load: Number(loadavg()[0].toFixed(2)),
    stated, archives: archives.length, bytes: archives.reduce((a, r) => a + r.bytes, 0),
    mountMs: loading === undefined ? null : Math.round(loading - (answered ?? opened)),
    loadS: seconds(done.status), status: done.status, note: done.note, checking: checked.length, checkingFirst: checked.slice(0, 3),
    hoverMs: h.ms, hover: h.answer,
  };
};
for (let round = 0; round < rounds; round++)
  for (const spec of specs) {
    const [module, line, word] = spec.split("|");
    const server = await serve({ root: site, noStore: ["/agda-algebras/"] });
    const chrome = await cdp.launch(process.env.CHROME);
    const { page } = chrome;
    try {
      await page.setViewport(1440, 900);
      await page.addInitScript(RECORDER);
      await page.navigate(`${server.origin}/`);
      await until(page, (s) => /open goal ·/.test(s.status) && !s.busy);
      console.log(JSON.stringify({ round, ...(await visit(page, server, module, line, word, true)) }));
      // Let the drive persist what the load wrote before the page is left.
      await sleep(5000);
      const before = await page.eval(() => performance.timeOrigin);
      await page.navigate(`${server.origin}/`);
      for (;;) { try { if ((await page.eval(() => performance.timeOrigin)) !== before) break; } catch {} await sleep(50); }
      await until(page, (s) => /open goal ·/.test(s.status) && !s.busy);
      console.log(JSON.stringify({ round, ...(await visit(page, server, module, line, word, false)) }));
    } catch (error) {
      console.log(JSON.stringify({ round, module, failed: String(error) }));
    } finally {
      await chrome.close();
      await server.close();
    }
  }

probes.give-at-the-end.mjs:
const repo = process.env.REPO;
const cdp = await import(`${repo}/scripts/browser-check/cdp.mjs`);
const { serve } = await import(`${repo}/scripts/browser-check/serve.mjs`);
const server = await serve({ root: process.argv[2], noStore: ["/agda-algebras/"] });
const chrome = await cdp.launch(process.env.CHROME);
const { page } = chrome;
const log = [];
await page.onConsole((e) => log.push(e));
await page.setViewport(1440, 900);
await page.navigate(`${server.origin}/`);
const sleep = (ms) => new Promise((d) => setTimeout(d, ms));
const st = () => page.eval(() => ({ status: document.querySelector(".inspector-status")?.textContent ?? "", busy: !!document.querySelector(".spin"), goals: document.querySelectorAll(".goal-card").length, problems: [...document.querySelectorAll(".problem-card pre")].map((p) => p.textContent.slice(0, 200)) }));
const until = async (p, ms = 120000) => { const t = Date.now(); for (;;) { const s = await st(); if (p(s)) return s; if (Date.now() - t > ms) throw new Error(JSON.stringify(s)); await sleep(100); } };
const submit = (value) => page.eval((value) => { const i = document.querySelector("#command-input"); i.value = value; i.dispatchEvent(new Event("input", { bubbles: true })); i.form.requestSubmit(); }, value);
await until((s) => /open goal ·/.test(s.status) && !s.busy);
await page.eval(() => document.querySelector(".cm-content").focus());
await page.press("End", "End", 35, 2);
await page.type("\nlast : Nat\nlast = ?\n");
await page.press("Enter", "Enter", 13, 2);
await until((s) => !s.busy && /2 open goals/.test(s.status));
const before = log.length;
await page.eval(() => [...document.querySelectorAll(".goal-card")].at(-1).click());
await sleep(500);
await until((s) => !s.busy);
await page.eval(() => [...document.querySelectorAll(".command-strip button")].find((b) => b.title.startsWith("Give")).click());
await sleep(200);
await submit("suc (suc zero)");
await until((s) => !s.busy && s.goals === 1);
await sleep(500);
console.log(JSON.stringify(await st()), JSON.stringify(log.slice(before).filter((e) => e.type === "error").map((e) => e.text.slice(0, 160))));
await chrome.close(); await server.close();

probes.whole-mine.mjs:
// The page's moduleCopy (src/lib/playground.ts) over every module of
// agda-algebras at the pin, each copy /wholemine/W<k>.lagda.md checked by
// native Agda 2.9.0 at the page's commit.
import { readFileSync, writeFileSync } from "node:fs";
import { spawn } from "node:child_process";
const [helper, here, repo] = process.argv.slice(2);
const { moduleCopy } = await import(helper);
const AGDA = "/nix/store/1axa6adsvwbz7wbck03d7wbsfdr1x8hq-Agda-2.9.0-bin/bin/agda";
const DIR = `${here}/wholemine`;
writeFileSync(`${DIR}/wholemine.agda-lib`, "name: wholemine\ndepend: standard-library-2.3 agda-algebras\ninclude: .\n");
const modules = JSON.parse(readFileSync(`${repo}/static/agda-algebras-modules.json`, "utf8")).modules;
const jobs = modules.map((m, k) => {
  const source = readFileSync(`${here}/src/agda-algebras/src/${m.name.split(".").join("/")}.lagda.md`, "utf8");
  const name = `W${k}`;
  const text = moduleCopy(source, m.name, name);
  if (text !== undefined) writeFileSync(`${DIR}/${name}.lagda.md`, text);
  return { module: m.name, name, made: text !== undefined, changedLines: text === undefined ? null : text.split("\n").filter((l, i) => l !== source.split("\n")[i]).length };
});
const run = (job) => new Promise((done) => {
  if (!job.made) return done({ ...job, exit: null });
  let out = "";
  const p = spawn(AGDA, ["+RTS", "-M3G", "-RTS", `${job.name}.lagda.md`], { cwd: DIR, env: { ...process.env, AGDA_DIR: `${here}/agdadir-w` } });
  p.stdout.on("data", (d) => (out += d));
  p.stderr.on("data", (d) => (out += d));
  p.on("close", (code) => {
    const checking = [...out.matchAll(/Checking (\S+) \(/g)].map((x) => x[1]);
    done({ ...job, exit: code, checked: checking.filter((n) => n !== job.name).length, error: /error: \[(\w+)\]/.exec(out)?.[1] ?? null });
  });
});
const results = [];
let next = 0;
await Promise.all(Array.from({ length: 6 }, async () => { while (next < jobs.length) results.push(await run(jobs[next++])); }));
writeFileSync(`${here}/whole-mine.json`, JSON.stringify(results, null, 1));
console.log(JSON.stringify({ checked: `${results.filter((r) => r.exit === 0).length}/${results.length}`, renamedOneLine: results.filter((r) => r.changedLines === 1).length, libraryRechecked: results.reduce((n, r) => n + (r.checked ?? 0), 0), errors: results.filter((r) => r.exit !== 0).map((r) => [r.module, r.error]) }));

probes.sel-mine.mjs:
// The page's selectionCopy (src/lib/playground.ts) over the reader's 278
// selections (sel-results-3.json: a module and 1-based source lines), each
// copy checked by native Agda 2.9.0 at the page's commit.
import { readFileSync, writeFileSync } from "node:fs";
import { spawn } from "node:child_process";
const [helper, here] = process.argv.slice(2);
const { selectionCopy } = await import(helper);
const AGDA = "/nix/store/1axa6adsvwbz7wbck03d7wbsfdr1x8hq-Agda-2.9.0-bin/bin/agda";
const DIR = `${here}/selmine`;
writeFileSync(`${DIR}/selmine.agda-lib`, "name: selmine\ndepend: standard-library-2.3 agda-algebras\ninclude: .\n");
const jobs = JSON.parse(readFileSync(`${here}/sel-results-3.json`, "utf8")).map((entry, k) => {
  const source = readFileSync(`${here}/src/agda-algebras/src/${entry.module.split(".").join("/")}.lagda.md`, "utf8");
  const lines = source.split("\n");
  const [a, b] = entry.lines.split("-").map(Number);
  const from = lines.slice(0, a - 1).reduce((n, l) => n + l.length + 1, 0);
  const to = lines.slice(0, b).reduce((n, l) => n + l.length + 1, 0) - 1;
  const name = `M${k}`;
  const copy = selectionCopy(source, entry.module, name, { from, to });
  if (copy) writeFileSync(`${DIR}/${name}.agda`, copy.text);
  return { module: entry.module, lines: entry.lines, indented: entry.indented, name, made: Boolean(copy), copyLines: copy?.text.split("\n").length, hidingRuleExit: entry.exit };
});
const run = (job) => new Promise((done) => {
  if (!job.made) return done({ ...job, exit: null });
  let out = "";
  const p = spawn(AGDA, ["+RTS", "-M3G", "-RTS", `${job.name}.agda`], { cwd: DIR, env: { ...process.env, AGDA_DIR: `${here}/agdadir-mine` } });
  p.stdout.on("data", (d) => (out += d));
  p.stderr.on("data", (d) => (out += d));
  p.on("close", (code) => {
    const checking = [...out.matchAll(/Checking (\S+) \(/g)].map((m) => m[1]);
    const error = /error: \[(\w+)\]/.exec(out)?.[1] ?? null;
    done({ ...job, exit: code, checked: checking.filter((n) => n !== job.name).length, error });
  });
});
const results = [];
let next = 0;
await Promise.all(Array.from({ length: 6 }, async () => {
  while (next < jobs.length) results.push(await run(jobs[next++]));
}));
results.sort((x, y) => Number(x.name.slice(1)) - Number(y.name.slice(1)));
writeFileSync(`${here}/sel-mine.json`, JSON.stringify(results, null, 1));
const ok = (r) => r.exit === 0;
const top = results.filter((r) => !r.indented), ind = results.filter((r) => r.indented);
console.log(JSON.stringify({ all: `${results.filter(ok).length}/${results.length}`, topLevel: `${top.filter(ok).length}/${top.length}`, indented: `${ind.filter(ok).length}/${ind.length}`, libraryRechecked: results.reduce((n, r) => n + (r.checked ?? 0), 0), errors: Object.entries(results.filter((r) => !ok(r)).reduce((m, r) => ((m[r.error] = (m[r.error] ?? 0) + 1), m), {})) }));

switchingBack.probe:
// Copilot round 1, finding 1: a chapter loaded with a goal, another chapter
// shown (mounted, not loaded, so Agda still holds the first), then the
// first shown again: are its goal markers Agda's, and do goal commands work?
const repo = process.env.REPO;
const cdp = await import(`${repo}/scripts/browser-check/cdp.mjs`);
const { serve } = await import(`${repo}/scripts/browser-check/serve.mjs`);
const server = await serve({ root: process.argv[2], noStore: ["/agda-algebras/"] });
const chrome = await cdp.launch(process.env.CHROME);
const { page } = chrome;
const log = [];
await page.onConsole((e) => log.push(e));
await page.setViewport(1440, 900);
const sleep = (ms) => new Promise((d) => setTimeout(d, ms));
const st = () => page.eval(() => ({
  status: document.querySelector(".inspector-status")?.textContent?.trim() ?? "",
  busy: !!document.querySelector(".spin"),
  tab: document.querySelector(".editor-tab.active")?.getAttribute("title") ?? null,
  markers: [...document.querySelectorAll(".agda-goal-marker")].map((m) => m.textContent),
  result: document.querySelector(".result-card pre")?.textContent ?? null,
  goals: [...document.querySelectorAll(".goal-card .goal-number")].map((g) => g.textContent.trim()),
  goalTypes: [...document.querySelectorAll(".goal-card .goal-content")].map((g) => g.textContent.trim()),
  err: document.querySelector(".action-error span")?.textContent ?? null,
  minibuffer: !!document.querySelector("#command-input"),
  zz: [...document.querySelectorAll(".cm-content .cm-line")].map((l) => l.textContent).filter((l) => l.startsWith("zz")),
}));
const until = async (p, what, ms = 120000) => { const t = Date.now(); for (;;) { const s = await st(); if (p(s)) return s; if (Date.now() - t > ms) throw new Error(`${what}: ${JSON.stringify(s)}`); await sleep(100); } };
const open = async (id) => { await page.eval((id) => document.querySelector(`.explorer [data-id="${id}"]`).focus(), id); await page.press("Enter", "Enter", 13); };
try {
  await page.navigate(`${server.origin}/`);
  await until((s) => /open goal ·/.test(s.status) && !s.busy, "first check");
  await open("plfa:part1/Naturals");
  await until((s) => s.tab === "/plfa/part1/Naturals.lagda.md" && !s.busy, "Naturals shown");
  await page.eval(() => document.querySelector(".cm-content").focus());
  await page.press("End", "End", 35, 2);
  await page.type("\n```agda\nzz : ℕ\nzz = {! !}\n```\n");
  await page.press("Enter", "Enter", 13, 2);
  let s = await until((s) => !s.busy && /open goal/.test(s.status), "Naturals' check");
  console.log("1. Naturals loaded:", s.status, "goal types", JSON.stringify(s.goalTypes));
  await open("plfa:part1/Induction");
  s = await until((s) => s.tab === "/plfa/part1/Induction.lagda.md" && !s.busy, "Induction shown");
  await sleep(1500);
  s = await st();
  console.log("2. Induction shown (mounted, not loaded):", JSON.stringify({ status: s.status, busy: s.busy }));
  await page.eval(() => [...document.querySelectorAll(".editor-tab")].find((t) => t.getAttribute("title") === "/plfa/part1/Naturals.lagda.md").querySelector(".editor-tab-open").click());
  s = await until((s) => s.tab === "/plfa/part1/Naturals.lagda.md" && !s.busy, "Naturals again");
  await sleep(1000);
  // The hole: two lines up from the end, inside its braces.
  await page.eval(() => document.querySelector(".cm-content").focus());
  await page.press("End", "End", 35, 2);
  await page.press("ArrowUp", "ArrowUp", 38);
  await page.press("ArrowUp", "ArrowUp", 38);
  await page.press("End", "End", 35);
  await page.press("ArrowLeft", "ArrowLeft", 37);
  await page.press("ArrowLeft", "ArrowLeft", 37);
  await sleep(300);
  console.log("3. Naturals again, cursor in the hole; editor's goal markers:", JSON.stringify((await st()).markers));
  await page.type("zero");
  await sleep(300);
  await page.press("c", "KeyC", 67, 2);
  await page.press(" ", "Space", 32, 2);
  s = await until((s) => !s.busy && (s.err !== null || !s.zz.some((l) => l.includes("{!"))), "give", 60000).catch((e) => ({ timeout: String(e) }));
  console.log("4. zero typed in the hole, Ctrl-c Ctrl-Space:", JSON.stringify({ status: s.status, err: s.err, zz: s.zz, markers: s.markers, timeout: s.timeout }));
} catch (e) { console.log("FAILED", String(e)); }
console.log("console errors:", JSON.stringify(log.filter((e) => e.type === "error" || e.type === "exception").map((e) => e.text.slice(0, 160))));
await chrome.close(); await server.close();
